// Your values first: they win because Bootstrap's defaults use !default
$primary: #6f42c1;
$font-family-sans-serif: "Inter", system-ui, sans-serif;
$border-radius: .75rem;
$spacer: 1.25rem;

// Then the whole framework
@import "../node_modules/bootstrap/scss/bootstrap";

// Your own rules can follow and may use Bootstrap's mixins and variables
.hero {
  padding: $spacer * 3 0;
  @include media-breakpoint-up(lg) {
    padding: $spacer * 5 0;
  }
}

// 1. Functions first, so tint-color() and shade-color() are available
@import "../node_modules/bootstrap/scss/functions";

// 2. Variable overrides
$tertiary: #0b7285;

// 3. Bootstrap's variables for both colour modes
@import "../node_modules/bootstrap/scss/variables";
@import "../node_modules/bootstrap/scss/variables-dark";

// 4. Map overrides: the colour itself and its 5.3 variants
$theme-colors: map-merge($theme-colors, ("tertiary": $tertiary));
$theme-colors-text: map-merge($theme-colors-text, ("tertiary": shade-color($tertiary, 60%)));
$theme-colors-bg-subtle: map-merge($theme-colors-bg-subtle, ("tertiary": tint-color($tertiary, 80%)));
$theme-colors-border-subtle: map-merge($theme-colors-border-subtle, ("tertiary": tint-color($tertiary, 60%)));
$theme-colors-text-dark: map-merge($theme-colors-text-dark, ("tertiary": tint-color($tertiary, 40%)));
$theme-colors-bg-subtle-dark: map-merge($theme-colors-bg-subtle-dark, ("tertiary": shade-color($tertiary, 80%)));
$theme-colors-border-subtle-dark: map-merge($theme-colors-border-subtle-dark, ("tertiary": shade-color($tertiary, 40%)));

// 5. The rest of the required files
@import "../node_modules/bootstrap/scss/maps";
@import "../node_modules/bootstrap/scss/mixins";
@import "../node_modules/bootstrap/scss/root";

// 6. Only the parts this project uses
@import "../node_modules/bootstrap/scss/utilities";
@import "../node_modules/bootstrap/scss/reboot";
@import "../node_modules/bootstrap/scss/type";
@import "../node_modules/bootstrap/scss/containers";
@import "../node_modules/bootstrap/scss/grid";
@import "../node_modules/bootstrap/scss/buttons";
@import "../node_modules/bootstrap/scss/alert";
@import "../node_modules/bootstrap/scss/helpers";

// 7. The utility API last: it generates the utility classes from the maps
@import "../node_modules/bootstrap/scss/utilities/api";

// With the other variable overrides (step 2)
$enable-shadows: true;
$enable-negative-margins: true;

// After @import "../node_modules/bootstrap/scss/utilities" and before utilities/api
$utilities: map-merge(
  $utilities,
  (
    "cursor": (
      property: cursor,
      class: cursor,
      values: auto pointer grab,
    ),
  )
);
